-- 42_MANUAL_LEADS.SQL
-- A lead a person found on their own (owner, 2026-10-23: "Add a feature to send custom mail to a lead that we
-- find on our own, as in lead is not generated by software and then there should be an option to select the
-- category it belongs to and then the usual"). tools/manual_lead.py adds it from the Leads page's Add a lead.
--
-- Four projects take new leads and contacts only from Apollo, and send only to addresses Apollo verified (owner,
-- 2026-10-19; sql/37, sql/38). A lead a person found by hand is the owner's exception to that:
--   * the lead: each of those projects lists 'manual' in sourcing.allowed_sources (its config), which the
--     entity trigger of sql/37 already reads;
--   * its contact: an address a person typed in is theirs to vouch for, and Apollo will never have seen it, so a
--     contact written as source 'manual', verifier 'person' (only tools/manual_lead.py writes that pair) may be
--     added, drafted, approved and sent in an Apollo project (both contact triggers and contact_allowed below).
-- Everything else is unchanged:
--   * a bounced address still ranks -1000 (contact_rank: status 'invalid') and is never used;
--   * every other contact in an Apollo project still needs to come from Apollo, verified;
--   * Clipping, with no Apollo policy, keeps its own behavior.

create or replace function contact_allowed(p_entity uuid, p_source text, p_verifier text, p_status text)
returns boolean language sql stable as $$
    select not exists (
        select 1 from entities e join segments s on s.id=e.segment_id
        where e.id=p_entity and s.config->'sourcing'->>'contacts'='apollo'
    ) or (coalesce(p_source='apollo',false) and coalesce(p_verifier='apollo',false)
          and coalesce(p_status='valid',false))
      -- a person typed it in, for a lead they found (tools/manual_lead.py)
      or (coalesce(p_source='manual',false) and coalesce(p_verifier='person',false))
$$;

create or replace function enforce_apollo_verified_contact() returns trigger language plpgsql as $$
declare enforced boolean;
begin
    select coalesce(s.config->'sourcing'->>'contacts'='apollo',false) into enforced
    from entities e join segments s on s.id=e.segment_id where e.id=new.entity_id;
    if not coalesce(enforced,false) then return new; end if;
    -- Bounce/verification downgrades are always allowed. They immediately make
    -- the address ineligible, without deleting historical correspondence.
    if tg_op='UPDATE' then
        if new.email is not distinct from old.email and new.entity_id=old.entity_id
           and new.source is not distinct from old.source and new.verifier is not distinct from old.verifier
           and (new.email_status is not distinct from old.email_status or new.email_status <> 'valid') then
            return new;
        end if;
    end if;
    -- an address a person typed in for a lead they found (sql/42)
    if new.source = 'manual' and new.verifier = 'person' then
        return new;
    end if;
    if new.source is distinct from 'apollo' or
       (new.email is not null and (new.email_status is distinct from 'valid' or new.verifier is distinct from 'apollo')) then
        raise exception 'This project accepts only Apollo-verified work emails.' using errcode='23514';
    end if;
    return new;
end;
$$;

create or replace function enforce_apollo_contact_source() returns trigger as $$
declare policy jsonb;
begin
    select s.config->'sourcing' into policy
      from entities e join segments s on s.id = e.segment_id where e.id = new.entity_id;
    if policy->>'contacts' = 'apollo' and new.source is distinct from 'apollo'
       -- an address a person typed in for a lead they found (sql/42)
       and not (new.source = 'manual' and new.verifier = 'person') then
        raise exception 'This project accepts new contacts only from Apollo.' using errcode = '23514';
    end if;
    return new;
end;
$$ language plpgsql;

-- the rule, read back: an Apollo project now takes a typed-in address, and still refuses a scraped one
select s.slug,
       contact_allowed(e.id, 'manual', 'person', 'unverified') as typed_in,
       contact_allowed(e.id, 'site_scrape', null, 'unverified') as scraped
from segments s
join lateral (select id from entities where segment_id = s.id limit 1) e on true
where s.is_active order by s.slug;
